// Flat garment illustrations for colourways that have neither a photograph nor
// a 3D mockup. Drawn from the print spec in content/products.ts, in the
// garment colour, on the same dark backdrop the mockups use, and labelled
// "Illustration" in the UI. They fill the catalogue honestly until the
// garments are shot. Regenerated by `npm run images` via prepare-images.mjs.
import sharp from "sharp";
import { readFile } from "node:fs/promises";

const OUT = "public/images/products";
const PAPER = "#EDE7DC";
const INK = "#0E0D12";
const BRICK = "#9C2736";

const monoSvg = await readFile("public/images/brand/monogram.svg", "utf8");
const MONO_D = monoSvg.match(/ d="([^"]+)"/)[1];
const [VX, VY, VW, VH] = monoSvg.match(/viewBox="([^"]+)"/)[1].split(" ").map(Number);

const hex2rgb = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
const rgb2hex = (c) => "#" + c.map((v) => Math.round(Math.max(0, Math.min(255, v))).toString(16).padStart(2, "0")).join("");
const mix = (a, b, t) => rgb2hex(hex2rgb(a).map((v, i) => v + (hex2rgb(b)[i] - v) * t));

/** Monogram centred at (cx, cy) with height h. */
function mono(cx, cy, h, fill, stroke) {
  const s = h / VH;
  const w = VW * s;
  const paint = stroke ? `stroke="${stroke}" stroke-width="${(12 / s).toFixed(1)}" stroke-linejoin="round" paint-order="stroke"` : "";
  return `<g transform="translate(${(cx - w / 2).toFixed(1)} ${(cy - h / 2).toFixed(1)}) scale(${s.toFixed(5)}) translate(${-VX} ${-VY})"><path d="${MONO_D}" fill="${fill}" ${paint}/></g>`;
}

/** Wordmark set along a sleeve: from (x1,y1) towards (x2,y2). */
function wordmark(x1, y1, x2, y2, fill, size = 30, length = 340) {
  const ang = (Math.atan2(y2 - y1, x2 - x1) * 180) / Math.PI;
  return `<text x="${x1}" y="${y1}" transform="rotate(${ang.toFixed(1)} ${x1} ${y1})" font-family="Georgia, 'Times New Roman', serif" font-weight="700" font-size="${size}" fill="${fill}" dominant-baseline="middle" textLength="${length}" lengthAdjust="spacingAndGlyphs">MENTAL TOUGHNESS</text>`;
}

const stitch = (d, col) => `<path d="${d}" fill="none" stroke="${col}" stroke-width="2.5" stroke-dasharray="7 6" opacity=".55"/>`;

/**
 * Each garment is drawn in a 1000×1000 box. `c` is the palette derived from
 * the colourway hex; `print` is the ink colour for the artwork.
 */
const garments = {
  tee({ c, print, twoColour }) {
    const body = "M400 195 Q500 290 600 195 L748 222 L882 405 L790 462 L722 392 L722 878 Q500 902 278 878 L278 392 L210 462 L118 405 L252 222 Z";
    return `
      ${shadow(500, 900, 330, 26)}
      <path d="${body}" fill="url(#cloth)" stroke="${c.rim}" stroke-width="2"/>
      <path d="M278 392 L210 462 L232 470 Z M722 392 L790 462 L768 470 Z" fill="${c.deep}" opacity=".5"/>
      <path d="M400 195 Q500 160 600 195 Q500 215 400 195 Z" fill="${c.deep}"/>
      <path d="M400 195 Q500 290 600 195" fill="none" stroke="url(#rib)" stroke-width="22"/>
      ${stitch("M300 855 Q500 878 700 855", c.tint)}
      ${stitch("M868 412 L784 466", c.tint)}${stitch("M132 412 L216 466", c.tint)}
      ${twoColour ? mono(500, 520, 380, BRICK, PAPER) : mono(500, 520, 380, print)}`;
  },
  longsleeve({ c, print }) {
    const body = "M400 195 Q500 290 600 195 L748 222 L892 690 L800 718 L722 400 L722 878 Q500 902 278 878 L278 400 L200 718 L108 690 L252 222 Z";
    return `
      ${shadow(500, 900, 330, 26)}
      <path d="${body}" fill="url(#cloth)" stroke="${c.rim}" stroke-width="2"/>
      <path d="M278 400 L222 620 L278 470 Z M722 400 L778 620 L722 470 Z" fill="${c.deep}" opacity=".45"/>
      <path d="M400 195 Q500 160 600 195 Q500 215 400 195 Z" fill="${c.deep}"/>
      <path d="M400 195 Q500 290 600 195" fill="none" stroke="url(#rib)" stroke-width="22"/>
      <path d="M118 655 L212 683 M882 655 L788 683" stroke="url(#rib)" stroke-width="40" stroke-linecap="butt"/>
      ${stitch("M300 855 Q500 878 700 855", c.tint)}
      ${mono(600, 330, 95, print)}
      ${wordmark(747, 300, 831, 650, print)}`;
  },
  crewneck({ c, print }) {
    const body = "M395 200 Q500 262 605 200 L760 228 L900 700 L806 728 L730 420 L730 860 L270 860 L270 420 L194 728 L100 700 L240 228 Z";
    return `
      ${shadow(500, 905, 360, 28)}
      <path d="${body}" fill="url(#cloth)" stroke="${c.rim}" stroke-width="2"/>
      <path d="M270 420 L214 640 L270 495 Z M730 420 L786 640 L730 495 Z" fill="${c.deep}" opacity=".45"/>
      <path d="M395 200 Q500 168 605 200 Q500 222 395 200 Z" fill="${c.deep}"/>
      <path d="M395 200 Q500 262 605 200" fill="none" stroke="url(#rib)" stroke-width="30"/>
      <rect x="270" y="860" width="460" height="46" fill="url(#rib)"/>
      <path d="M110 665 L204 693 M890 665 L796 693" stroke="url(#rib)" stroke-width="46"/>
      ${mono(605, 338, 90, print)}
      ${wordmark(756, 300, 838, 660, print)}`;
  },
  tank({ c, print }) {
    const body = "M410 190 Q500 330 590 190 L688 172 Q655 335 722 445 L722 878 Q500 902 278 878 L278 445 Q345 335 312 172 Z";
    return `
      ${shadow(500, 900, 300, 24)}
      <path d="${body}" fill="url(#cloth)" stroke="${c.rim}" stroke-width="2"/>
      <path d="M410 190 Q500 330 590 190 M688 172 Q655 335 722 445 M312 172 Q345 335 278 445" fill="none" stroke="${c.deep}" stroke-width="14"/>
      <path d="M410 190 Q500 165 590 190 Q500 205 410 190 Z" fill="${c.deep}"/>
      ${stitch("M300 855 Q500 878 700 855", c.tint)}
      ${mono(500, 430, 110, print)}`;
  },
  bucket({ c, print }) {
    return `
      ${shadow(500, 700, 380, 26)}
      <path d="M288 540 L140 566 Q500 722 860 566 L712 540 Q500 588 288 540 Z" fill="url(#cloth)" stroke="${c.rim}" stroke-width="2"/>
      <path d="M288 540 L140 566 Q500 722 860 566 L712 540 Q500 588 288 540 Z" fill="${c.tint}" opacity=".22"/>
      <path d="M318 330 Q500 250 682 330 L712 540 Q500 588 288 540 Z" fill="url(#cloth)" stroke="${c.rim}" stroke-width="2"/>
      <path d="M318 330 Q500 250 682 330 L712 540 Q500 588 288 540 Z" fill="#000" opacity=".12"/>
      <path d="M318 330 Q500 250 682 330 Q500 374 318 330 Z" fill="${c.tint}" opacity=".55"/>
      <path d="M288 540 Q500 588 712 540" fill="none" stroke="${c.deep}" stroke-width="3"/>
      ${stitch("M170 585 Q500 705 830 585", c.tint)}${stitch("M215 600 Q500 690 785 600", c.tint)}${stitch("M258 612 Q500 676 742 612", c.tint)}
      ${mono(500, 452, 118, print)}`;
  },
  beanie({ c }) {
    return `
      ${shadow(500, 700, 320, 24)}
      <path d="M285 600 Q285 245 500 235 Q715 245 715 600 Z" fill="url(#cloth)" stroke="${c.rim}" stroke-width="2"/>
      <path d="M340 600 Q330 300 500 245 M420 600 Q410 280 500 240 M500 600 L500 238 M580 600 Q590 280 500 240 M660 600 Q670 300 500 245" fill="none" stroke="${c.deep}" stroke-width="3" opacity=".5"/>
      <rect x="262" y="562" width="476" height="128" rx="22" fill="url(#ribBig)" stroke="${c.rim}" stroke-width="2"/>
      <rect x="446" y="592" width="108" height="68" rx="3" fill="${PAPER}"/>
      ${mono(500, 626, 50, INK)}`;
  },
};

function shadow(cx, cy, rx, ry) {
  return `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="#000" opacity=".55" filter="url(#blur)"/>`;
}

function palette(hex) {
  return {
    base: hex,
    tint: mix(hex, "#FFFFFF", 0.18),
    shade: mix(hex, "#000000", 0.28),
    deep: mix(hex, "#000000", 0.5),
    rim: mix(hex, "#FFFFFF", 0.32),
  };
}

const FRAMES = { tees: [1433, 1600], fleece: [1600, 1281], headwear: [1600, 1600] };

function svgFor({ garment, hex, print, twoColour, frame }) {
  const [W, H] = FRAMES[frame];
  const c = palette(hex);
  const scale = frame === "fleece" ? 1.15 : frame === "headwear" ? 1.4 : 1.35;
  const tx = (W - 1000 * scale) / 2;
  const ty = frame === "headwear" ? (H - 1000 * scale) / 2 + 30 : (H - 1000 * scale) / 2;
  const art = garments[garment]({ c, print, twoColour });
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
  <defs>
    <radialGradient id="bg" cx="50%" cy="40%" r="72%"><stop offset="0" stop-color="#2B2A31"/><stop offset="1" stop-color="#0B0A0E"/></radialGradient>
    <linearGradient id="cloth" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${c.tint}"/><stop offset=".55" stop-color="${c.base}"/><stop offset="1" stop-color="${c.shade}"/></linearGradient>
    <pattern id="rib" width="10" height="10" patternUnits="userSpaceOnUse"><rect width="10" height="10" fill="${c.shade}"/><rect width="4" height="10" fill="${c.base}"/></pattern>
    <pattern id="ribBig" width="16" height="16" patternUnits="userSpaceOnUse"><rect width="16" height="16" fill="${c.shade}"/><rect width="7" height="16" fill="${c.tint}" opacity=".8"/></pattern>
    <filter id="blur" x="-50%" y="-200%" width="200%" height="500%"><feGaussianBlur stdDeviation="22"/></filter>
    <filter id="grain" x="0" y="0" width="100%" height="100%"><feTurbulence type="fractalNoise" baseFrequency=".9" numOctaves="2" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/></filter>
  </defs>
  <rect width="${W}" height="${H}" fill="url(#bg)"/>
  <rect width="${W}" height="${H}" filter="url(#grain)" opacity=".045"/>
  <g transform="translate(${tx.toFixed(1)} ${ty.toFixed(1)}) scale(${scale})">${art}</g>
</svg>`;
}

/** key → spec. Keys match content/products.ts image keys. */
export const illustrations = {
  "illus-core-tee-black": { garment: "tee", hex: "#131316", twoColour: true, frame: "tees" },
  "illus-long-sleeve-tee-black": { garment: "longsleeve", hex: "#131316", print: PAPER, frame: "tees" },
  "illus-long-sleeve-tee-red": { garment: "longsleeve", hex: "#9C2736", print: PAPER, frame: "tees" },
  "illus-crewneck-sweatshirt-black": { garment: "crewneck", hex: "#131316", print: PAPER, frame: "fleece" },
  "illus-crewneck-sweatshirt-red": { garment: "crewneck", hex: "#9C2736", print: PAPER, frame: "fleece" },
  "illus-tank-top-black": { garment: "tank", hex: "#131316", print: PAPER, frame: "tees" },
  "illus-tank-top-olive": { garment: "tank", hex: "#5A5B45", print: PAPER, frame: "tees" },
  "illus-bucket-hat-black": { garment: "bucket", hex: "#131316", print: PAPER, frame: "headwear" },
  "illus-bucket-hat-orange": { garment: "bucket", hex: "#FE732E", print: INK, frame: "headwear" },
  "illus-beanie-black": { garment: "beanie", hex: "#131316", frame: "headwear" },
  "illus-beanie-red": { garment: "beanie", hex: "#9C2736", frame: "headwear" },
};

/** Renders every illustration and returns manifest entries keyed like the images above. */
export async function illustrate(manifest = {}) {
  for (const [key, spec] of Object.entries(illustrations)) {
    const dest = `products/${key}.jpg`;
    const info = await sharp(Buffer.from(svgFor(spec)))
      .jpeg({ quality: 90, progressive: true, mozjpeg: true })
      .toFile(`${OUT}/${key}.jpg`);
    manifest[key] = { src: `/images/${dest}`, width: info.width, height: info.height };
    console.log(`${dest}  ${info.width}×${info.height}  ${(info.size / 1024).toFixed(0)}KB (illustration)`);
  }
  return manifest;
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].split("/").pop())) {
  await illustrate();
}
